content.content:
# Shared helpers for the KeystoneOS run ledger and job registry.
# Dot-source this file; it defines functions and does no work on its own.
#
# The ledger answers one question nothing else could answer: "did this job actually
# succeed today?" Before it existed, the scheduler's own history was the only record,
# and that records "the process exited", not "the work happened".

Set-StrictMode -Version Latest

function Get-KeystoneRoot {
    (Resolve-Path -LiteralPath (Join-Path $PSScriptRoot "..")).Path
}

function Get-KeystoneDevRoot {
    # DEV is the parent of the KeystoneOS repo.
    (Resolve-Path -LiteralPath (Join-Path (Get-KeystoneRoot) "..")).Path
}

function Expand-JobToken {
    param(
        [Parameter(Mandatory)][AllowEmptyString()][string]$Value,
        [datetime]$Date = (Get-Date)
    )
    $out = $Value
    $out = $out.Replace("{REPO}", (Get-KeystoneRoot))
    $out = $out.Replace("{DEV}", (Get-KeystoneDevRoot))
    $out = $out.Replace("{USERPROFILE}", $HOME)
    $out = $out.Replace("{DATE}", $Date.ToString("yyyy-MM-dd"))
    $out
}

function Get-JobRegistry {
    param([string]$Path)
    if (-not $Path) { $Path = Join-Path (Get-KeystoneRoot) "data/jobs.json" }
    if (-not (Test-Path -LiteralPath $Path)) { throw "Job registry not found: $Path" }
    $raw = Get-Content -Raw -LiteralPath $Path
    ($raw | ConvertFrom-Json).jobs
}

function Get-JobDefinition {
    param(
        [Parameter(Mandatory)][string]$Id,
        [string]$RegistryPath
    )
    $job = Get-JobRegistry -Path $RegistryPath | Where-Object { $_.id -eq $Id }
    if (-not $job) { throw "Unknown job id '$Id'. Check data\jobs.json." }
    $job
}

function Get-LedgerPath {
    param([string]$Root)
    if (-not $Root) { $Root = Get-KeystoneRoot }
    Join-Path $Root "outputs/run-ledger.json"
}

# --- locking -----------------------------------------------------------------
# A named mutex, not a PID file: when the holding process is killed outright (which
# is exactly what a Restart Manager shutdown does), Windows marks the mutex abandoned
# and the next waiter acquires it cleanly. A PID file would be left behind as a stale
# lock and would need heuristics to break.

function New-KeystoneMutex {
    param([Parameter(Mandatory)][string]$Name)
    $safe = $Name -replace '[^A-Za-z0-9_-]', '_'
    try {
        [System.Threading.Mutex]::new($false, "Global\KeystoneOS-$safe")
    } catch [System.UnauthorizedAccessException] {
        # Global namespace can be denied by policy; a session-local mutex still gives
        # mutual exclusion between the scheduled task and the reconciler.
        [System.Threading.Mutex]::new($false, "Local\KeystoneOS-$safe")
    }
}

function Invoke-WithMutex {
    param(
        [Parameter(Mandatory)][string]$Name,
        [Parameter(Mandatory)][scriptblock]$Body,
        [int]$TimeoutMs = 0,
        [switch]$SkipIfBusy
    )
    $mutex = New-KeystoneMutex -Name $Name
    $held = $false
    try {
        try {
            $held = $mutex.WaitOne($TimeoutMs)
        } catch [System.Threading.AbandonedMutexException] {
            # Previous holder died without releasing. We now own it.
            $held = $true
        }
        if (-not $held) {
            if ($SkipIfBusy) { return $null }
            throw "Could not acquire lock '$Name' within ${TimeoutMs}ms."
        }
        & $Body
    }
    finally {
        if ($held) { try { $mutex.ReleaseMutex() } catch { } }
        $mutex.Dispose()
    }
}

function Test-JobLockBusy {
    param([Parameter(Mandatory)][string]$Id)
    $mutex = New-KeystoneMutex -Name "job-$Id"
    try {
        $got = $false
        try { $got = $mutex.WaitOne(0) }
        catch [System.Threading.AbandonedMutexException] { $got = $true }
        if ($got) { try { $mutex.ReleaseMutex() } catch { } }
        -not $got
    }
    finally { $mutex.Dispose() }
}

# --- ledger read/write -------------------------------------------------------

function Read-RunLedger {
    param([string]$Path)
    if (-not $Path) { $Path = Get-LedgerPath }
    if (-not (Test-Path -LiteralPath $Path)) {
        return [pscustomobject]@{ version = 1; jobs = [pscustomobject]@{} }
    }
    try {
        $raw = Get-Content -Raw -LiteralPath $Path
        if (-not $raw -or -not $raw.Trim()) {
            return [pscustomobject]@{ version = 1; jobs = [pscustomobject]@{} }
        }
        $raw | ConvertFrom-Json
    } catch {
        # A truncated ledger (killed mid-write) must not take the whole system down.
        # Preserve the damaged file for inspection and start clean.
        $bak = "$Path.corrupt-$((Get-Date).ToString('yyyyMMddHHmmss'))"
        try { Move-Item -LiteralPath $Path -Destination $bak -Force } catch { }
        [pscustomobject]@{ version = 1; jobs = [pscustomobject]@{} }
    }
}

function Get-JobEntries {
    param(
        [Parameter(Mandatory)]$Ledger,
        [Parameter(Mandatory)][string]$Id
    )
    if (-not $Ledger.PSObject.Properties['jobs']) { return @() }
    $jobs = $Ledger.jobs
    if (-not $jobs -or -not $jobs.PSObject.Properties[$Id]) { return @() }
    @($jobs.$Id)
}

function Add-LedgerEntry {
    param(
        [Parameter(Mandatory)][string]$Id,
        [Parameter(Mandatory)][string]$Status,
        [int]$ExitCode = 0,
        [datetime]$StartedAt = (Get-Date),
        [datetime]$FinishedAt = (Get-Date),
        [string]$Trigger = "scheduled",
        [switch]$MadeUp,
        [string]$Note,
        [string]$Path,
        [int]$KeepPerJob = 60
    )
    if (-not $Path) { $Path = Get-LedgerPath }
    $dir = Split-Path -Parent $Path
    if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }

    $entry = [ordered]@{
        date        = $StartedAt.ToString("yyyy-MM-dd")
        status      = $Status
        exitCode    = $ExitCode
        startedAt   = $StartedAt.ToString("o")
        finishedAt  = $FinishedAt.ToString("o")
        durationSec = [int]([math]::Round(($FinishedAt - $StartedAt).TotalSeconds))
        trigger     = $Trigger
        madeUp      = [bool]$MadeUp
    }
    if ($Note) { $entry.note = $Note }

    Invoke-WithMutex -Name "run-ledger" -TimeoutMs 15000 -Body {
        $ledger = Read-RunLedger -Path $Path
        if (-not $ledger.PSObject.Properties['jobs'] -or -not $ledger.jobs) {
            $ledger | Add-Member -NotePropertyName jobs -NotePropertyValue ([pscustomobject]@{}) -Force
        }
        $existing = @(Get-JobEntries -Ledger $ledger -Id $Id)
        $updated = @([pscustomobject]$entry) + $existing
        if ($updated.Count -gt $KeepPerJob) { $updated = $updated[0..($KeepPerJob - 1)] }
        $ledger.jobs | Add-Member -NotePropertyName $Id -NotePropertyValue $updated -Force

        $tmp = "$Path.tmp"
        ($ledger | ConvertTo-Json -Depth 10) | Set-Content -LiteralPath $tmp -Encoding UTF8
        Move-Item -LiteralPath $tmp -Destination $Path -Force
    } | Out-Null

    [pscustomobject]$entry
}

# --- success determination ---------------------------------------------------

function Test-LedgerSuccessOn {
    param(
        [Parameter(Mandatory)][string]$Id,
        [datetime]$Date = (Get-Date),
        [string]$Path
    )
    $ledger = Read-RunLedger -Path $Path
    $key = $Date.ToString("yyyy-MM-dd")
    [bool](@(Get-JobEntries -Ledger $ledger -Id $Id) |
        Where-Object { $_.date -eq $key -and $_.status -eq 'ok' } |
        Select-Object -First 1)
}

function Get-LedgerFailureCountOn {
    param(
        [Parameter(Mandatory)][string]$Id,
        [datetime]$Date = (Get-Date),
        [string]$Path
    )
    $ledger = Read-RunLedger -Path $Path
    $key = $Date.ToString("yyyy-MM-dd")
    @(Get-JobEntries -Ledger $ledger -Id $Id |
        Where-Object { $_.date -eq $key -and $_.status -ne 'ok' }).Count
}

function Test-Probe {
    <#
      Evaluates a job's successProbe / authWarnProbe against its own log output.
      Returns $false when the probe cannot be evaluated (missing file), never throws —
      an unevaluable probe must not be read as success.
    #>
    param(
        $Probe,
        [datetime]$Date = (Get-Date)
    )
    if (-not $Probe) { return $false }
    try {
        $path = Expand-JobToken -Value $Probe.path -Date $Date
        if (-not (Test-Path -LiteralPath $path)) { return $false }

        switch ($Probe.kind) {
            'fileModifiedToday' {
                $item = Get-Item -LiteralPath $path
                return ($item.LastWriteTime.Date -eq $Date.Date)
            }
            'fileContains' {
                $pattern = Expand-JobToken -Value $Probe.pattern -Date $Date
                return [bool](Select-String -LiteralPath $path -Pattern $pattern -Quiet)
            }
            default { return $false }
        }
    } catch {
        return $false
    }
}

function Get-NewestWriteTime {
    <#
      Newest LastWriteTime for a file, or for the top-level files of a directory.
      Directory form is deliberate: browser profiles relocate individual files
      between Chrome versions (Cookies moved to Network\Cookies), so pinning a
      single filename is a silent breakage waiting to happen.
    #>
    param([Parameter(Mandatory)][string]$Path)
    if (-not (Test-Path -LiteralPath $Path)) { return $null }
    $item = Get-Item -LiteralPath $Path
    if ($item.PSIsContainer) {
        $files = @(Get-ChildItem -LiteralPath $Path -File -ErrorAction SilentlyContinue)
        if (-not $files) { return $null }
        return ($files | Measure-Object LastWriteTime -Maximum).Maximum
    }
    $item.LastWriteTime
}

function Test-WarningSuperseded {
    <#
      True when the condition a warning probe matched has since been repaired.

      A warning probe matches a line written earlier today. Once the underlying
      problem is fixed the line is still there, so the warning would keep firing
      for the rest of the day. 'resolvedIfNewer' names something whose mtime moves
      when the fix happens (a re-authenticated browser profile); newer than the log
      that carried the complaint means the complaint is stale.
    #>
    param(
        $Probe,
        [datetime]$Date = (Get-Date)
    )
    if (-not $Probe) { return $false }
    if (-not $Probe.PSObject.Properties['resolvedIfNewer'] -or -not $Probe.resolvedIfNewer) { return $false }
    try {
        $sourceTime = Get-NewestWriteTime -Path (Expand-JobToken -Value $Probe.path -Date $Date)
        $fixTime = Get-NewestWriteTime -Path (Expand-JobToken -Value $Probe.resolvedIfNewer -Date $Date)
        if ($null -eq $sourceTime -or $null -eq $fixTime) { return $false }
        return ($fixTime -gt $sourceTime)
    } catch {
        return $false
    }
}

function Test-JobCompleteOn {
    <# Succeeded today, per the ledger OR the job's own log. #>
    param(
        [Parameter(Mandatory)]$Job,
        [datetime]$Date = (Get-Date),
        [string]$LedgerPath
    )
    if (Test-LedgerSuccessOn -Id $Job.id -Date $Date -Path $LedgerPath) { return $true }
    $probe = if ($Job.PSObject.Properties['successProbe']) { $Job.successProbe } else { $null }
    Test-Probe -Probe $probe -Date $Date
}

# --- schedule matching -------------------------------------------------------

function Test-ScheduledOn {
    param(
        [Parameter(Mandatory)]$Job,
        [datetime]$Date = (Get-Date)
    )
    switch ($Job.schedule.kind) {
        'daily'    { return $true }
        'weekdays' { return ($Date.DayOfWeek -ne [DayOfWeek]::Saturday -and $Date.DayOfWeek -ne [DayOfWeek]::Sunday) }
        'weekly'   { return ($Date.DayOfWeek.ToString() -eq $Job.schedule.dayOfWeek) }
        default    { return $false }
    }
}

function Get-ScheduledDateTime {
    param(
        [Parameter(Mandatory)]$Job,
        [datetime]$Date = (Get-Date)
    )
    $parts = $Job.schedule.at.Split(':')
    $Date.Date.AddHours([int]$parts[0]).AddMinutes([int]$parts[1])
}

function Test-InMakeupWindow {
    param(
        [Parameter(Mandatory)]$Job,
        [datetime]$Now = (Get-Date)
    )
    if (-not $Job.PSObject.Properties['makeupWindow'] -or -not $Job.makeupWindow) { return $true }
    $from = $Job.makeupWindow.from.Split(':')
    $to = $Job.makeupWindow.to.Split(':')
    $start = $Now.Date.AddHours([int]$from[0]).AddMinutes([int]$from[1])
    $end = $Now.Date.AddHours([int]$to[0]).AddMinutes([int]$to[1])
    ($Now -ge $start -and $Now -le $end)
}

